def check_good_function(g):
    # Condition (3): g(1)=1
    if g(1) != 1:
        print(f"FAIL: Condition (3). g(1)={g(1)}")
        return False

    # Testing conditions (1) and (2) with various pairs (a, b)
    # Since checking all distinct a, b in R is impossible, we test specific cases.

    # Test Case 1: Positive numbers
    a, b = 2, 3
    if a != b:
        gab = g(a * b)
        if gab == 0:
            if g(a) != 0 and g(b) != 0:
                print(f"FAIL: Condition (1) for ({a}, {b}). g({a*b})=0 but g({a})!=0 and g({b})!=0")
                return False
        else:
            # g(a*b) != 0
            LHS = (g(a) - g(b)) / (a - b)
            RHS = (g(a) * g(b)) / g(a * b)
            if abs(LHS - RHS) > 1e-9:
                print(f"FAIL: Condition (2) for ({a}, {b}). LHS={LHS}, RHS={RHS}")
                return False

    # Test Case 2: Mixed signs
    a, b = 2, -3
    if a != b:
        gab = g(a * b) # g(-6)
        if gab == 0:
            if g(a) != 0 and g(b) != 0:
                print(f"FAIL: Condition (1) for ({a}, {b}). g({a*b})=0 but g({a})!=0 and g({b})!=0")
                return False
        else:
            # g(a*b) != 0
            LHS = (g(a) - g(b)) / (a - b)
            RHS = (g(a) * g(b)) / g(a * b)
            if abs(LHS - RHS) > 1e-9:
                print(f"FAIL: Condition (2) for ({a}, {b}). LHS={LHS}, RHS={RHS}")
                return False

    # Test Case 3: Negative numbers
    a, b = -2, -3
    if a != b:
        gab = g(a * b) # g(6)
        if gab == 0:
            if g(a) != 0 and g(b) != 0:
                print(f"FAIL: Condition (1) for ({a}, {b}). g({a*b})=0 but g({a})!=0 and g({b})!=0")
                return False
        else:
            # g(a*b) != 0
            LHS = (g(a) - g(b)) / (a - b)
            RHS = (g(a) * g(b)) / g(a * b)
            if abs(LHS - RHS) > 1e-9:
                print(f"FAIL: Condition (2) for ({a}, {b}). LHS={LHS}, RHS={RHS}")
                return False

    return True

def g_identity(x):
    return x

is_g_identity_good = check_good_function(g_identity)
print(f"Is g(x)=x a good function? {is_g_identity_good}")
